  ;

inputOutputSection
  : INPUT_OUTPUT SECTION DOT fileControlClause*
  ;

fileControlClause
  : SELECT IDENTIFIER ASSIGN TO fileSource fileOrgClause? accessModeClause? recordKeyClause? fileStatusClause?
  ;

fileSource
