grammar MAPL;

mapUnit
    : mapDecl* EOF
    ;

mapDecl
    : 'map' IDENT 'from' IDENT 'to' IDENT ';' mapBody 'end' ';'
    ;

mapBody
    : mapStmt*
    ;

mapStmt
    : assignStmt
    | assignDefaultStmt
    | functionAssignStmt
    | ifStmt
    | forStmt
    | validateStmt
    ;

fieldPath
    : IDENT ('.' IDENT)*
    ;

assignStmt
    : fieldPath ':=' fieldPath ';'
    ;

assignDefaultStmt
    : fieldPath ':=' fieldPath 'default' expr ';'
    ;

functionAssignStmt
    : fieldPath ':=' functionCall ';'
    ;

functionCall
    : IDENT '(' exprList? ')'
    ;

ifStmt
    : 'if' expr 'then' mapBody ('else' mapBody)? 'end' ';'
    ;

forStmt
    : 'for' 'each' fieldPath 'as' IDENT mapBody 'end' ';'
    ;

validateStmt
    : 'validate' expr ';'
    ;

exprList
    : expr (',' expr)*
    ;

expr
    : logicalOrExpr
    ;

logicalOrExpr
    : logicalAndExpr ('or' logicalAndExpr)*
    ;

logicalAndExpr
    : equalityExpr ('and' equalityExpr)*
    ;

equalityExpr
    : relationalExpr (('=' | '<>') relationalExpr)*
    ;

relationalExpr
    : additiveExpr (('<' | '<=' | '>' | '>=') additiveExpr)*
    ;

additiveExpr
    : multiplicativeExpr (('+' | '-') multiplicativeExpr)*
    ;

multiplicativeExpr
    : unaryExpr (('*' | '/' | 'mod') unaryExpr)*
    ;

unaryExpr
    : ('not' | '-') unaryExpr

grammar Pascalish;

// Case-insensitive so programs can use lowercase, UPPERCASE or mixed keywords.
options { caseInsensitive = true; }

// ============================================================
// Top-level compilation unit
// ============================================================

compilationUnit
    : decl* EOF
    ;

decl
    : programDecl
    | serviceDecl
    | daemonDecl
    | typeDecl
    | classDecl
    | varDecl
    | queueDecl
    | fileDecl
    | roleDecl
    | libraryDecl
    | useDecl
    | interopDecl
    | routerDecl
    | mapperDecl
    | importDecl
    | blockStmt
    ;

// ============================================================
// Runtime placement and unit declarations
// ============================================================

placement
    : 'on' ('local' | 'parent' | 'child' | 'sibling' | 'alternate')
    ;

programDecl
    : 'program' stringOrIdent placement? ';' unitDecl* block? unitEnd
    ;

serviceDecl
    : 'service' stringOrIdent placement? ';'? unitDecl* (serviceBody | serviceEndpoint* 'end')? unitEnd
    ;

daemonDecl
    : 'daemon' stringOrIdent placement? daemonSchedule? ';'? unitDecl* block? unitEnd
    ;

// Wirth compilation units terminate with '.'; ';' is still accepted while the
// existing corpus is migrated.
unitEnd
    : '.'
    | ';'
    ;

