    ;

useDecl
    : 'use' stringOrIdent ('as' IDENT)? ';'
    ;

interopDecl
    : 'interop' interopKind stringOrIdent ('as' IDENT)? ';'
    ;

interopKind
    : 'wfl'
    | 'workflow'
    | 'cobolish'
    | 'pascalish'
    ;

importDecl
    : 'import' librarianImportItems 'from' 'data' 'librarian' ';'
    | 'import' importTarget 'from' serviceProvider ';'
    ;

// Data Librarian imports are declarations of available types, not linked
// runtime libraries. Keep the imported names in the program map for resolution
// by the caller.
librarianImportItems
    : importTarget (',' importTarget)*
    ;

importTarget
    : IDENT
    | STRING
    ;

serviceProvider
    : stringOrIdent
    ;

// ============================================================
// Router declaration
// ============================================================

routerDecl
    : 'router' stringOrIdent 'input' stringValue routerHeaderProp* 'begin' outputDecl* 'end' ';'
    ;

routerHeaderProp
