    | '(' stringOrIdent (',' stringOrId

n' stringValue
    | 'enabled' booleanValue
    | 'service' stringValue
    | 'methods' verbList
    ;

verbList
    : stringOrIdent
    | '(' stringOrIdent (',' stringOrIdent)* ')'
    ;

outputDecl
    : 'output' stringValue outputTypeMeta? 'when' pl0Snippet 'transform' pl0Snippet ';'
    ;

outputTypeMeta
    : 'type' typeRef
    | 'types' typeRefList
    ;

typeRefList
    : typeRef
    | '(' typeRef (',' typeRef)* ')'
    ;

// ============================================================
// Mapper declaration
// ============================================================

mapperDecl
    : 'mapper' stringOrIdent 'source' typeRef 'target' typeRef mapperHeaderProp* 'begin' mapDecl* 'end' ';'
    ;

mapperHeaderProp
    : 'description' stringValue
    | 'enabled' booleanValue
    ;

mapDecl
    : 'map' stringValue 'to' stringValue ('using' pl0Snippet)? ';'
    ;

// ============================================================
// Service body and HTTP endpoints
// ============================================================

serviceBody
    : 'begin' serviceBodyElement* 'end'
    ;

serviceBodyElement
    : serviceLocalDecl
    | serviceStmt
    ;

serviceLocalDecl
    : unitDecl
    ;

serviceEndpoint
    : httpVerb stringValue endpointAccepts? endpointReturns? ';' blockStmt
    ;

httpVerb
    : 'get' | 'post' |

'
    | 'm'
    ;

syncStmt
    : 'sync' IDENT
    ;

subflowStmt
    : 'subflow' stringValue subflowOption*
    ;

subflowOption
    : 'on' stringOrIdent
    | 'with' exprList
    | 'timeout' expr timeUnit
    | 'into' IDENT
    ;

returnStmt
    : 'return' 'success'? expr?
    ;

fileStmt
    : 'open' IDENT 'for' ('read' | 'write')
    | 'read' IDENT 'into' IDENT
    | 'write' IDENT 'with' expr
    | 'close' IDENT
    ;

// ============================================================
// Expressions
// ============================================================

lvalue
    : IDENT ('.' IDENT)*
    ;

qualifiedName
    : IDENT ('.' qualifiedPart)*
    ;

// HTTP verbs are keywords, so allow them after a dot (e.g. httpVerb.post).
qualifiedPart
    : IDENT
    | httpVerb
    ;

stringOrIdent
    : STRING
    | IDENT
    ;

stringValue
    : STRING
    ;

booleanValue
    : 'true'
    | 'false'
    ;

exprList
    : expr (',' expr)*
    ;

expr
    : logicalOrExpr
    ;

logicalOrExpr
    : logicalAndExpr ('or' logicalAndExpr)*
    ;

logicalAndExpr
    : equalityExpr ('and' equalityExpr)*
    ;

equalityExpr
    : relationalExpr (('=' | '<>') relationalExpr)*
    ;

relationalExpr
    : additiveExpr (('<' | '<=' | '>' | '>=') additiveExpr)*
    ;

additiveExpr
    : multiplicativeExpr (('+' |

Expr (('=' | '<>') relationalExpr)*
    ;

relationalExpr
    : additiveExpr (('<' | '<=' | '>' | '>=') additiveExpr)*
    ;

additiveExpr
    : multiplicativeExpr (('+' | '-') multiplicativeExpr)*
    ;

multiplicativeExpr
    : unaryExpr (('*' | '/' | 'mod') unaryExpr)*
    ;

unaryExpr
    : ('not' | '-') unaryExpr
    | primaryExpr
    ;

primaryExpr
    : NUMBER
    | STRING
    | 'true'
    | 'false'
    | qualifiedName '(' exprList? ')'
    | lvalue
    | '(' expr ')'
    ;

// ============================================================
// Lexer rules
// ============================================================

IDENT
    : [a-zA-Z_] [a-zA-Z_0-9]*
    ;

NUMBER
    : [0-9]+ ('.' [0-9]+)?
    ;

STRING
    : '"' (~["\\] | '\\' .)* '"'
    | '\'' (~['\\] | '\\' .)* '\''
    ;

LINE_COMMENT
    : '//' ~[\r\n]* -> skip
    ;

BLOCK_COMMENT
    : '/*' .*? '*/' -> skip
    ;

BRACE_COMMENT
    : '{' .*? '}' -> skip
    ;

WS
    : [ \t\r\n]+ -> skip
    ;

grammar Vbish;

options { caseInsensitive = true; }

compilationUnit
  : optionExplicit? runtimeDecl? (interopDecl | roleDecl | libraryDecl | useDecl | importDecl | routeDecl | systemDecl | databaseDecl | topLevelDecl)* EOF
  ;

optionExplicit
  : OPTION EXPLICIT
  ;

runtimeDecl
  : PULSE? (SERVICE | DAEMON | PROGRAM) stringOrIdentifier (ON placement)? (EVERY NUMBER intervalUnit)?
  ;

placement
  : LOCAL | PARENT | CHILD | SIBLING | ALTERNATE
  ;

intervalUnit
  : MS | S | M | SECOND | SECONDS
  ;

interopDecl
  : INTEROP interopKind STRING_LITERAL (AS IDENTIFIER)?
  ;

interopKind
  : PASCALISH | COBOLISH | VBISH | WFL | WORKFLOW
  ;

topLevelDecl
