{ Phase (array indexing) smoke test: runtime-variable array read/write via ARR_GET/ARR_SET. }

program ArrayIndexSmoke;

var
  nums: array[0..4] of integer;
  i: integer;

begin
  for i := 0 to 4 do
    nums[i] := i * 10;
  writeln('nums[3] = ', nums[3]);
  i := 2;
  nums[i] := nums[i] + 1;
  writeln('nums[2] = ', nums[2])
end.

service blink10 on local;
  var led, i: integer;

  get "/" returns string;
  begin
    led := fsm.open('device', 'LEDPIN', 'led', 2);
    for i := 1 to 10 do
    begin
      fsm.set(led, 'power', 'on');
      delayMs(1000);
      fsm.set(led, 'power', 'off');
      delayMs(1000);
    end;
    fsm.close(led);
    return "blink10 complete";
  end
end.

