program MutualRecursionEvenOdd;

var
  parity: integer;

procedure IsEven(n: integer);
begin
  if n = 0 then
    parity := 1
  else
    IsOdd(n - 1)
end;

procedure IsOdd(n: integer);
begin
  if n = 0 then
    parity := 0
  else
    IsEven(n - 1)
end;

procedure PrintChecks(i, max: integer);
begin
  if i <= max then
  begin
    IsEven(i);
    writeln('even(', i, ')=', parity);
    IsOdd(i);
    writeln('odd(', i, ')=', parity);
    PrintChecks(i + 1, max)
  end
end;

begin
  PrintChecks(0, 11)
end.

program RecursiveFactorial;

procedure PrintFactRange(i, max, acc: integer);
begin
  if i <= max then
  begin
    writeln('fact(', i, ')=', acc);
    PrintFactRange(i + 1, max, acc * (i + 1))
  end
end;

begin
  PrintFactRange(0, 10, 1)
end.

program FactorialService;

var n, result, i : integer;

procedure factorial(x : integer);
begin
  if x <= 1 then
    result := 1
  else begin
    factorial(x - 1);
    result := result * x
  end
end;

begin
  n := src;
  if (n >= 0) and (n <= 10) and (not (src = 'Invalid input')) then begin
    if (n = 0) and (not (src = '0')) then
      writeln('Invalid input')
    else begin
      result := 1;
      factorial(n);
      writeln(result)
    end
  end else
    writeln('Invalid input')
end.

service factorialService on local;
  var n, factorial, i: integer;

  get "/" accepts integer returns integer;
  begin
    n := parseInt(sourceValue("n"));
    factorial := 0;
    if n >= 1 then
      if n <= 10 then
      begin
        factorial := 1;
        for i := 1 to n do
          factorial := factorial * i;
      end;
    return factorial;
  end
end.

