{ Complex arithmetic with operator syntax. }

program ComplexShowcase;

use "imaginary";

var
  z: Complex;
  w: Complex;
  t: Complex;
  modulus: real;
  realPart: real;

begin
  z.re := 3.0;
  z.im := 4.0;
  w.re := 1.0;
  w.im := 0.0 - 2.0;

  writeln('z = ', z.toString());
  writeln('w = ', w.toString());

  t := z + w;
  writeln('z + w = ', t.toString());

  t := z - w;
  writeln('z - w = ', t.toString());

  t := z * w;
  writeln('z * w = ', t.toString());

  t := z / w;
  writeln('z / w = ', t.toString());

  t := z.conj();
  writeln('conj z = ', t.toString());

  { a real widens into a Complex implicitly }
  t := z + 1.0;
  writeln('z + 1 = ', t.toString());

  t := z * 2.0;
  writeln('z * 2 = ', t.toString());

  modulus := z.abs();
  writeln('abs z = ', modulus);

  { explicit narrowing back to real }
  realPart := real(z);
  writeln('real z = ', realPart)
end.

{ Logical names only: WFL redefines server/schema/connection bindings at deploy time. }
database messageStore type sqlserver
  server "localhost" catalog "pulse" schema "dbo"
  connection secret "messagestore-connection";

table incomingMessages of text in messageStore
  columns (reference: text, payload: text, status: text);

daemon "incoming-messages-daemon" refresh 2 s;

queue mt103Inbound queue<mt103>;

var msg : mt103;
var seen : string;

begin
  dequeue mt103Inbound into msg;
  if msg <> '' then
  begin
    select status from incomingMessages where payload = msg into seen;
    if seen = '' then
      insert into incomingMessages (reference, payload, status) values (msg, msg, 'received')
    else
      update incomingMessages set status := 'duplicate' where payload = msg
  end
end.

program LedBlinkTen;

var
  led: integer;
  i: integer;

begin
  led := fsm.open('device', 'LEDPIN', 'led', 2);
  for i := 1 to 10 do
  begin
    fsm.set(led, 'power', 'on');
    delayMs(1000);
    fsm.set(led, 'power', 'off');
    delayMs(1000);
  end;
  fsm.close(led);
end.

