program FactorialService;

var n, result, i : integer;

procedure factorial(x : integer);
begin
  if x <= 1 then
    result := 1
  else begin
    factorial(x - 1);
    result := result * x
  end
end;

begin
  n := src;
  if (n >= 0) and (n <= 10) and (not (src = 'Invalid input')) then begin
    if (n = 0) and (not (src = '0')) then
      writeln('Invalid input')
    else begin
      result := 1;
      factorial(n);
      writeln(result)
    end
  end else
    writeln('Invalid input')
end.

program FactorialService;

var i, result : integer;
begin
  readln(i);
  if (i >= 0) and (i <= 10) then begin
    result := 1;
    while not (i = 0) do begin
      result := result * (i - 0.5); // This line is incorrect, factorial should be calculated with integers only without floating point operations here
      i := i - 1;
    end;
    writeln(result)
  end else
    writeln('Invalid input')
end.

program "dual-node-atomic-check";

service "risk_check";
begin
  return '{"success":true,"replyJson":"{\"stage\":\"risk_check\",\"node\":\"childNode\"}"}';
end;

service "limits_check";
begin
  return '{"success":true,"replyJson":"{\"stage\":\"limits_check\",\"node\":\"childNode\"}"}';
end;

begin
  cobegin
    async subflow "risk_check" on "childNode" with req timeout 5 s into h_node1;
    async subflow "limits_check" on "childNode" with req timeout 5 s into h_node2;
  coend;

  wait all (h_node1, h_node2) into (r_node1, r_node2) timeout 8 s on error fail transaction "subtasks timeout or transport error";
  return success merged_reply;
end.

